var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

app.MapGet("/products/{id:int}", (int id) =>
{
    return Results.Ok(new { Id = id, Name = "Product " + id });
});

app.MapPost("/orders/{orderId:guid}", (Guid orderId) =>
{
    return Results.Accepted("/orders/{orderId}", new { orderId });
});

// Fallback for unmatched routes
app.MapFallback(() => Results.NotFound("Route not found"));

app.Run();

app.Use(async (context, next) =>
{
    var endpoint = context.GetEndpoint();
    if (endpoint is null)
    {
        await next();
        return;
    }

    var displayName = endpoint.DisplayName;
    var routePattern = (endpoint as RouteEndpoint)?.RoutePattern;

    context.Response.Headers["X-Endpoint"] = displayName ?? "unknown";
    await next();
});
